import{_ as n,I as o,c,o as t,a5 as a,b as s,w as i,a as l,J as d,a6 as u}from"./chunks/framework.BmNIwhaK.js";const C=JSON.parse('{"title":"Attribute-Based Access Control (ABAC) & Crawled Data Security Architecture","description":"Attribute-Based Access Control (ABAC) architecture and security token auditing framework for collected unstructured data and inter-agent communication","frontmatter":{"title":"Attribute-Based Access Control (ABAC) & Crawled Data Security Architecture","shortTitle":"ABAC Data Security","category":"Runtime Stability & Security","sort":11,"description":"Attribute-Based Access Control (ABAC) architecture and security token auditing framework for collected unstructured data and inter-agent communication","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/synccrawl/abac-data-security"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synccrawl/abac-data-security"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synccrawl/abac-data-security"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synccrawl/abac-data-security"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synccrawl/abac-data-security"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Attribute-Based Access Control (ABAC) & Crawled Data Security Architecture | Empasy Docs"}],["meta",{"property":"og:description","content":"Attribute-Based Access Control (ABAC) architecture and security token auditing framework for collected unstructured data and inter-agent communication"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/synccrawl/abac-data-security"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attribute-Based Access Control (ABAC) & Crawled Data Security Architecture | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Attribute-Based Access Control (ABAC) architecture and security token auditing framework for collected unstructured data and inter-agent communication"}]]},"headers":[],"relativePath":"en/synccrawl/abac-data-security.md","filePath":"en/synccrawl/abac-data-security.md","lastUpdated":1795293539000}'),h={name:"en/synccrawl/abac-data-security.md"};function m(A,e,b,y,g,p){const r=o("Mermaid");return t(),c("div",null,[e[1]||(e[1]=a('<h1 id="attribute-based-access-control-abac-crawled-data-security-architecture" tabindex="-1">Attribute-Based Access Control (ABAC) &amp; Crawled Data Security Architecture <a class="header-anchor" href="#attribute-based-access-control-abac-crawled-data-security-architecture" aria-label="Permalink to “Attribute-Based Access Control (ABAC) &amp; Crawled Data Security Architecture”">​</a></h1><h2 id="_1-background-and-limitations-of-rbac" tabindex="-1">1. Background and Limitations of RBAC <a class="header-anchor" href="#_1-background-and-limitations-of-rbac" aria-label="Permalink to “1. Background and Limitations of RBAC”">​</a></h2><p>Traditional Role-Based Access Control (RBAC) determines access to API endpoints based on user roles (such as <code>ROLE_USER</code> or <code>ROLE_ADMIN</code>). However, in environments where collected datasets and multiple agents collaborate, RBAC exhibits clear limitations for composite authorization checks:</p><ol><li><strong>Lack of Tenant and Department Data Isolation</strong>: Even when two users share the same collector role, fine-grained Data Ownership controls are required so that a user in Division B cannot access competitor analysis data collected by Division A.</li><li><strong>Inter-Agent Communication Trust Model</strong>: Internal backend worker-to-worker communication (Pod-to-Pod) must validate explicit tokens and attributes rather than implicitly bypassing standard user session checks.</li><li><strong>Dynamic Blocking by Network Environment</strong>: Even with a valid administrator account, certain management tool invocations originating from external public networks outside the corporate internal network (VNet) must be blocked.</li></ol><p>To address these requirements, <code>SyncCrawl</code> adopts an <strong>Attribute-Based Access Control (ABAC)</strong> architecture that evaluates a combination of multi-dimensional Subject, Resource, and Environment attributes.</p>',5)),(t(),s(u,null,{default:i(()=>[d(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Req%5B%22API%20Call%20Request%20(Subject%20%2B%20Resource%20%2B%20Environment)%22%5D%20--%3E%20G1%7B%22Stage%201%3A%20Environment%20Gate%20(Deny-first)%3Cbr%2F%3ENetwork%20Location%20%2F%20Unauthorized%20Path%20Check%22%7D%0A%20%20%20%20G1%20--%20%22Internal-only%20endpoint%20accessed%20from%20external%20network%22%20--%3E%20Deny1%5B%22Immediate%20Deny%20(403%20Forbidden)%22%5D%0A%20%20%20%20G1%20--%20%22Pass%22%20--%3E%20G2%7B%22Stage%202%3A%20Coarse-Grained%20RBAC%20Check%3Cbr%2F%3EBaseline%20Role%20%2F%20Permission%20Verification%22%7D%0A%20%20%20%20G2%20--%20%22Missing%20role%22%20--%3E%20Deny2%5B%22Immediate%20Deny%20(403%20Forbidden)%22%5D%0A%20%20%20%20G2%20--%20%22Pass%22%20--%3E%20G3%7B%22Stage%203%3A%20Fine-Grained%20ABAC%20Evaluation%20(Allow-only)%3Cbr%2F%3EOwner%20Match%20%26%20Security%20Classification%20Check%22%7D%0A%20%20%20%20G3%20--%20%22Attribute%20conditions%20met%22%20--%3E%20Allow%5B%22Authorize%20Request%20%26%20Return%20Data%22%5D%0A%20%20%20%20G3%20--%20%22Attribute%20mismatch%22%20--%3E%20Deny3%5B%22Deny%20Access%20%26%20Record%20Security%20Audit%20Log%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-abac-attribute-inventory" tabindex="-1">2. ABAC Attribute Inventory <a class="header-anchor" href="#_2-abac-attribute-inventory" aria-label="Permalink to “2. ABAC Attribute Inventory”">​</a></h2><p>Authorization evaluation combines three standardized categories of attributes.</p><h3 id="_1-subject-attributes" tabindex="-1">1) Subject Attributes <a class="header-anchor" href="#_1-subject-attributes" aria-label="Permalink to “1) Subject Attributes”">​</a></h3><ul><li><code>userId / username</code>: Unique identifier of the requester</li><li><code>tenantId / orgId</code>: Multi-tenant and organizational unit identifier</li><li><code>roles / permissions</code>: Set of permissions granted under the existing RBAC model</li><li><code>agentToken</code>: Signed authentication token for internal system agent communication (<code>Signed Header</code>)</li></ul><h3 id="_2-resource-attributes" tabindex="-1">2) Resource Attributes <a class="header-anchor" href="#_2-resource-attributes" aria-label="Permalink to “2) Resource Attributes”">​</a></h3><ul><li><code>resourceId / ownerId</code>: Unique key of the collected dataset and owner identifier</li><li><code>resourceType</code>: Target object type being accessed (e.g., <code>CrawledDataset</code>, <code>Scenario</code>, <code>Credential</code>)</li><li><code>sensitivityClassification</code>: Data security classification level (<code>PUBLIC</code>, <code>INTERNAL</code>, <code>RESTRICTED</code>)</li></ul><h3 id="_3-environment-attributes" tabindex="-1">3) Environment Attributes <a class="header-anchor" href="#_3-environment-attributes" aria-label="Permalink to “3) Environment Attributes”">​</a></h3><ul><li><code>networkLocation</code>: Whether the request originates from internal VPC/AKS cluster traffic or a public internet gateway</li><li><code>endpointType</code>: Intended scope of the invoked URI (<code>INTERNAL_SYSTEM_API</code> vs <code>EXTERNAL_CLIENT_API</code>)</li></ul><hr><h2 id="_3-three-stage-policy-evaluation-precedence" tabindex="-1">3. Three-Stage Policy Evaluation Precedence <a class="header-anchor" href="#_3-three-stage-policy-evaluation-precedence" aria-label="Permalink to “3. Three-Stage Policy Evaluation Precedence”">​</a></h2><p>Authorization checks are evaluated sequentially inside a unified <code>AuthorizationContext</code> according to a strictly predefined precedence order:</p><ol><li><strong>Stage 1: Environment Gate (Deny-first)</strong>: <ul><li>Immediately blocks any external access detected through public ingress to internal agent-only endpoints (e.g., <code>/api/internal/worker/*</code>).</li></ul></li><li><strong>Stage 2: Coarse-Grained RBAC Check</strong>: <ul><li>Verifies that the requesting subject holds the baseline domain permission (e.g., <code>@PreAuthorize(&quot;hasPermission(&#39;crawling:read&#39;)&quot;)</code>).</li></ul></li><li><strong>Stage 3: Fine-Grained ABAC &amp; Data Ownership Check (Allow-only)</strong>: <ul><li>Verifies that the requester&#39;s <code>tenantId</code> matches the resource&#39;s tenant affiliation.</li><li>When the resource&#39;s security classification is <code>RESTRICTED</code>, it cross-checks the subject&#39;s clearance level and resource ownership (<code>ownerId</code>); if any single condition fails, access is denied.</li></ul></li></ol><hr><h2 id="_4-internal-agent-token-authentication-audit-trail" tabindex="-1">4. Internal Agent Token Authentication &amp; Audit Trail <a class="header-anchor" href="#_4-internal-agent-token-authentication-audit-trail" aria-label="Permalink to “4. Internal Agent Token Authentication &amp; Audit Trail”">​</a></h2><ul><li><strong>Signed Header Verification</strong>: <ul><li>When distributed worker agents (<code>smart-crawling-agent</code>) transmit collected data to the central server, they attach an <code>X-Sync-Agent-Token</code> header signed with a timestamp and secret key.</li></ul></li><li><strong>Replay Attack Prevention</strong>: <ul><li>Signed tokens are strictly limited to a 60-second validity window, and any attempt to reuse the same signed token is immediately blocked within the server&#39;s in-memory replay window.</li></ul></li><li><strong>Security Audit Reporting Integration</strong>: <ul><li>Every authorization evaluation result—both successes and failures—is recorded in a WORM audit log along with the source IP of unauthorized access attempts and the subject identifier for security compliance evidence.</li></ul></li></ul>',16))])}const k=n(h,[["render",m]]);export{C as __pageData,k as default};
